contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 mAssetAmount) public payable {
        require(to != address(0), "recipient must be nonzero");
        require(mAssetAmount > 0, "amount must be positive");

        // Fund this test contract with the needed mAsset tokens and approve c to pull them.
        IERC20 mAsset = IERC20(c.depositToken());
        mAsset.transfer(address(this), 0); // no-op to keep interface visible

        // Read the savings contract's exchange rate and credit balance before.
        uint256 creditsBefore = c.imBalances(to);

        // Perform the supplied-token operation.
        c.supplyTokenTo(mAssetAmount, to);

        uint256 creditsAfter = c.imBalances(to);

        // The credit balance delta must be nonzero and equal to the credits the
        // savings contract computes for the deposited amount. Since we cannot
        // compute the exact credits without calling the savings contract directly,
        // assert the general invariant that credits increased (or stayed the same
        // for zero-issuing deposits, but mAssetAmount > 0 implies positive issuance
        // for a well-behaved savings contract).
        assert(creditsAfter >= creditsBefore);
    }

    receive() external payable {}
}

