        uint256 liquidBefore = mAsset.balanceOf(address(this));
        uint256 cTokenBefore = mAsset.balanceOf(address(c));
        uint256 cBalanceBefore = address(c).balance;

        uint256 mAssetsActual = c.redeemToken(mAssetAmount);

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 liquidAfter = mAsset.balanceOf(address(this));
        uint256 cTokenAfter = mAsset.balanceOf(address(c));
        uint256 cBalanceAfter = address(c).balance;

        assert(cBalanceAfter == cBalanceBefore);
        assert(liquidAfter - liquidBefore == cTokenBefore - cTokenAfter);
        assert(mAssetsActual == liquidAfter - liquidBefore);
        assert(creditsBefore - creditsAfter >= 0);
    }

    receive() external payable {}
}

