contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        IERC20 mAsset = IERC20(c.depositToken());

        uint256 testBalBefore = mAsset.balanceOf(address(this));
        uint256 cBalBefore = mAsset.balanceOf(address(c));
        uint256 creditsBefore = c.balanceOfToken(address(this));

        uint256 actualAmount;
        bool reverted;
        try c.redeemToken(amount) returns (uint256 v) {
            actualAmount = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 testBalAfter = mAsset.balanceOf(address(this));
        uint256 cBalAfter = mAsset.balanceOf(address(c));
        uint256 creditsAfter = c.balanceOfToken(address(this));

        if (!reverted) {
            assert(
                testBalAfter - testBalBefore == actualAmount &&
                cBalBefore - cBalAfter == actualAmount &&
                creditsAfter <= creditsBefore
            );
        } else {
            assert(
                testBalAfter == testBalBefore &&
                cBalAfter == cBalBefore &&
                creditsAfter == creditsBefore
            );
        }
    }

    receive() external payable {}
}

