contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "must supply positive amount");
        require(redeemAmount > 0, "must redeem positive amount");

        uint256 mAssetBalanceBefore = IERC20(c.depositToken()).balanceOf(address(this));
        require(mAssetBalanceBefore >= supplyAmount, "insufficient mAsset balance for supply");

        // approve c to pull mAssets
        IERC20(c.depositToken()).approve(address(c), supplyAmount);

        // supply tokens to this contract (to = address(this))
        c.supplyTokenTo(supplyAmount, address(this));

        uint256 creditsAfterSupply = c.imBalances(address(this));
        require(creditsAfterSupply > 0, "no credits issued");

        // try to redeem an amount of mAsset; redeeming credits > creditsAfterSupply should revert
        uint256 mAssetBalanceBeforeRedeem = IERC20(c.depositToken()).balanceOf(address(this));
        bool redeemed;
        try c.redeemToken(redeemAmount) {
            redeemed = true;
        } catch {
            redeemed = false;
        }

        uint256 mAssetBalanceAfterRedeem = IERC20(c.depositToken()).balanceOf(address(this));
        uint256 creditsAfterRedeem = c.imBalances(address(this));

        if (redeemed) {
            // If redemption succeeded, the user's credits must decrease by at most creditsAfterSupply,
            // and the mAsset received must be > 0 (assuming redeemAmount > 0).
            assert(creditsAfterRedeem <= creditsAfterSupply);
            assert(mAssetBalanceAfterRedeem >= mAssetBalanceBeforeRedeem);
            // Since redeemAmount > 0, some mAsset must have been received.
            assert(mAssetBalanceAfterRedeem > mAssetBalanceBeforeRedeem);
        } else {
            // If redemption failed, the user's credits must be unchanged.
            assert(creditsAfterRedeem == creditsAfterSupply);
            // And the mAsset balance must be unchanged.
            assert(mAssetBalanceAfterRedeem == mAssetBalanceBeforeRedeem);
        }
    }

    receive() external payable {}
}

