    function run(address to, uint256 amount) public payable {
        require(to != address(0), "zero to");
        require(amount > 0, "zero amount");

        // Give this test contract enough mAsset to supply.
        // The constructor of C approves savings for max, and mAsset is the savings underlying.
        // We transfer amount from savings.underlying() to this contract via the ERC20 interface,
        // but we must not declare interfaces. Instead, use c.mAsset() returns IERC20, and call transferFrom? No.
