        // If the call reverts, require the observed balance to be unchanged.
        uint256 beforeCredits = c.imBalances(to);
        bool reverted;
        try c.supplyTokenTo(amount, to) { reverted = false; } catch { reverted = true; }
        uint256 afterCredits = c.imBalances(to);

        assert(
            (reverted && afterCredits == beforeCredits) ||
            (!reverted && afterCredits >= beforeCredits)
        );
    }

    receive() external payable {}
}

