contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemCredits) public payable {
        require(supplyAmount > 0, "supply amount must be positive");
        require(redeemCredits > 0, "redeem credits must be positive");

        address self = address(this);

        uint256 suppliedCredits = 0;
        uint256 redeemedUnderlying = 0;

        // The test contract must first acquire mAsset to supply. We use the
        // pre-existing balance if any; otherwise the supply call will revert
        // due to insufficient transferFrom allowance/balance, which is fine
        // for the general rule.
        uint256 mAssetBefore = IERC20(c.depositToken()).balanceOf(self);
        require(mAssetBefore >= supplyAmount, "insufficient mAsset balance for supply");

        IERC20(c.depositToken()).approve(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, self);
        uint256 creditsAfterSupply = c.imBalances(self);

        require(creditsAfterSupply >= redeemCredits, "not enough credits to redeem");

        redeemedUnderlying = c.redeemToken(redeemCredits);

        uint256 creditsAfterRedeem = c.imBalances(self);
        uint256 mAssetAfter = IERC20(c.depositToken()).balanceOf(self);

        // General rule: redeeming credits reduces the caller's imBalances by
        // exactly the credits burned (the amount passed to redeemToken, since
        // redeemToken burns credits via redeemUnderlying), and the underlying
        // mAsset balance does not decrease after the redeem call completes.
        // Because we required sufficient credits, creditsAfterRedeem must be
        // creditsAfterSupply - redeemCredits and mAssetAfter >= mAssetBefore.
        assert(creditsAfterRedeem == creditsAfterSupply - redeemCredits && mAssetAfter >= mAssetBefore);
    }

    receive() external payable {}
}

