    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount) public {
        require(mAssetAmount > 0, "amount must be positive");

        // If c has no credits (imBalances[address(this)] is 0), redeemToken will revert,
        // so we use a try/catch to capture that and make the rule conditional.
        bool reverted;
        uint256 returnedAmount;
        try c.redeemToken(mAssetAmount) returns (uint256 r) {
            returnedAmount = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // The returned amount must be positive when not reverting? Actually if mAssetAmount > 0 and no revert, returnedAmount could be 0 if exchange rate rounds down.
            // General rule: if the call succeeds, the returned amount equals the increase in the caller's mAsset balance
            // as observed via ERC20 Transfer events. Since we can't easily read events in a test, we use a different observable: the returned amount equals mAsset.balanceOf(address(this)) increase? But we can't read balance before and after because it's the same call.
            // But we can read mAsset balance before and after the call! The contract c holds the mAsset, and after redeemToken, it transfers mAssetsActual to msg.sender (this contract).
            // Wait, msg.sender is InvMutTest, so the transfer goes to InvMutTest. We can check mAsset.balanceOf(address(this)) before and after.
            // But we need to read mAsset before the call? The call is already done in try. We can't read before the call because the try is the first call changing state.
            // However, we can read mAsset.balanceOf(address(this)) before the call as a view call. But we already made the call. To fix, we need to read before, then call, then read after.
        }
    }
}

