contract InvMutTest {
    C c;
    uint256 private _beforeCredits;
    uint256 private _beforeExchangeRate;

    constructor(C _c) { c = _c; }

    function run() public payable {
        // Read-only observations before the state-changing call.
        _beforeExchangeRate = c.savings().exchangeRate();
        _beforeCredits = c.imBalances(address(this));

        uint256 amount = 1000;

        // Ensure the caller actually has enough underlying mAsset to transfer.
        require(c.mAsset().balanceOf(address(this)) >= amount, "setup: insufficient underlying");
        require(c.mAsset().allowance(address(this), address(c)) >= amount, "setup: insufficient allowance");

        c.supplyTokenTo(amount, address(this));

        uint256 afterCredits = c.imBalances(address(this));
        uint256 afterBalance = c.balanceOfToken(address(this));
        uint256 expectedCreditsDelta = _afterCreditsCompute(amount, _beforeExchangeRate);
        uint256 expectedBalance = (afterCredits * _beforeExchangeRate) / 1e18;

        assert(
            afterCredits == _beforeCredits + expectedCreditsDelta &&
            afterBalance >= expectedBalance &&
            afterBalance <= (afterCredits * _beforeExchangeRate) / 1e18
        );
    }

    function _afterCreditsCompute(uint256 amount, uint256 exchangeRate) private pure returns (uint256) {
        // credits = amount * 1e18 / exchangeRate, matching the savings contract's deposit savings.
        return (amount * 1e18) / exchangeRate;
    }
}

