contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to) public payable {
        require(amount > 0, "amount must be positive");
        require(to != address(0), "beneficiary must be nonzero");

        // setup: give this test contract enough mAsset and approve c to spend it.
        // We cannot mint mAsset directly; but the test contract can receive mAsset
        // from the savings contract only through c. Instead, use c's existing
        // mAsset allowance mechanism? Not available.

        // Use params: require that this contract already holds at least `amount`
        // mAsset. Callers of run must pre-fund. To observe balances of mAsset we
        // must go through c's public getter `mAsset()`.
        IERC20 mAsset = c.mAsset();
        require(mAsset.balanceOf(address(this)) >= amount, "insufficient mAsset balance");

        // approve c to transferFrom our mAsset
        mAsset.approve(address(c), amount);

        // record pre-supply credits for beneficiary
        uint256 creditsBefore = c.imBalances(to);

        // supply as a top-level statement
        c.supplyTokenTo(amount, to);

        uint256 creditsAfter = c.imBalances(to);
        uint256 credited = creditsAfter - creditsBefore; // no underflow expected

        // redeem the credits back to the beneficiary
        // To redeem, msg.sender must be the beneficiary, but c.redeemToken uses msg.sender
        // So if to != address(this), we cannot redeem for them. Require to == address(this).
        require(to == address(this), "beneficiary must be this contract for redemption");

        uint256 redeemAmount = creditsAfter; // redeem entire credited balance
        uint256 actual = c.redeemToken(redeemAmount);

        assert(credited > 0 && actual > 0);
    }

    receive() external payable {}
}

