contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to, uint256 exchangeRate) public {
        require(to != address(0), "beneficiary cannot be zero");
        require(exchangeRate > 0, "exchange rate must be positive");
        require(mAssetAmount > 0, "amount must be positive");

        IERC20 mAsset = c.mAsset();
        ISavingsContractV2 savings = c.savings();

        // Set up: caller must have enough mAsset to deposit.
        mAsset.safeApprove(address(c), mAssetAmount);
        mAsset.safeMint(address(this), mAssetAmount);

        // Read the exchange rate used by c's balanceOfToken.
        uint256 rate = savings.exchangeRate();

        uint256 balanceBefore = c.balanceOfToken(to);

        c.supplyTokenTo(mAssetAmount, to);

        uint256 balanceAfter = c.balanceOfToken(to);

        // The rule: depositing mAssetAmount should credit the recipient with credits
        // equal in value (in underlying mAsset terms) to the amount deposited.
        // In other words, balanceOfToken(to) - balanceBefore should equal the
        // mAsset value of the credits issued by savings.depositSavings, and that
        // value should be mAssetAmount (modulo exchange rate rounding), i.e.
        //   (balanceAfter - balanceBefore) * 1e18 / rate == mAssetAmount
        // for a savings contract that credits 1:1 in underlying terms.
        // Since we cannot call savings directly from the test and rely on its return
        // value, we instead assert an invariant that holds when savings is a
        // standard ERC-4626-like savings contract where credits are minted 1:1
        // with the underlying deposit.
        //
        // We make the rule general by allowing either:
        //   - the savings contract credits exactly mAssetAmount worth of credits, so
        //     the balance increase equals mAssetAmount, or
        //   - the savings contract is not a standard one, in which case we merely
        //     require the balance did not decrease.
        //
        // The accepted property is the strong one for a well-behaved savings contract:
        // after supplyTokenTo, the beneficiary's credited balance in mAsset terms
        // increases by exactly the deposited amount, assuming the savings contract
        // mints 1 credit per 1 mAsset deposited.
        assert(balanceAfter >= balanceBefore && (balanceAfter - balanceBefore) * 1e18 / rate == mAssetAmount);
    }

    receive() external payable {}
}

