        c.supplyTokenTo(mAssetAmount, to);

        uint256 balanceAfter = c.balanceOfToken(to);

        // General rule: with a 1:1 exchange rate, depositing mAssetAmount must
        // increase the credited balance by exactly mAssetAmount.
        assert(balanceAfter >= balanceBefore && balanceAfter - balanceBefore == mAssetAmount);
    }

    receive() external payable {}
}

