contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount, address user) public payable {
        require(user != address(0), "zero user");
        require(redeemAmount > 0, "redeem amount must be positive");
        require(address(this).balance >= 0, "balance check");

        // Setup: give this test contract some of the underlying mAsset and supply it to `user`.
        // We assume the test contract already has a positive mAsset balance from the test harness.
        // (If this assumption fails, the supply call itself reverts, which is fine for the rule.)
        c.supplyTokenTo(supplyAmount, user);

        // Read the user's credited balance before the attempted redemption.
        uint256 balBefore = c.imBalances(user);

        // Attempt to redeem more than the user's credited underlying.
        // Since redeemAmount is arbitrary, it may or may not exceed the credited balance.
        // We need a general rule that holds for all paths.
        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if redemption reverted, the user's credited balance must be unchanged.
        // This is the essential safety guarantee: failed redemptions do not mutate state.
        uint256 balAfter = c.imBalances(user);
        assert(reverted ? balAfter == balBefore : balAfter <= balBefore);
    }

    receive() external payable {}
}

