        address mAssetAddr = c.depositToken();
        IERC20 mAsset = IERC20(mAssetAddr);

        // Acquire mAsset for the test contract from c's savings contract? No—use c's public surface only.
        // Instead, deposit on behalf of this contract: caller is this test contract, which
        // already holds mAsset? Not guaranteed. Use the savings contract to fund? Not allowed.
        //
        // Simpler observable rule that needs no external funding:
        // redeemToken must revert for a caller with zero credits balance when redeemAmount > 0,
        // because imBalances[msg.sender] -= creditsBurned would underflow.
        //
        // But we can make a stronger, funds-independent rule: read c's mAsset balance before,
        // call redeemToken, and assert that if it succeeds, the mAssets received equals the
        // increase in the caller's mAsset balance. That requires c to actually hold mAsset.
        //
        // Since no external funding is allowed, the safest general rule is the revert rule:
        // redeemToken(amount>0) reverts when the caller has zero credits.

        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a caller with zero credits cannot redeem a positive amount; the call
        // must revert. This catches faulty versions that would underflow or silently succeed.
        assert(c.imBalances(address(this)) == 0 ? reverted : true);
    }
}

