    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        require(supplyAmount > 0);
        require(redeemAmount > 0);

        // Read the caller's balance before supplying.
        uint256 beforeImBal = c.imBalances(address(this));

        // Supply mAsset into the yield source.
        c.supplyTokenTo(supplyAmount, address(this));

        // Read the caller's balance after supplying.
        uint256 afterImBal = c.imBalances(address(this));

        // The call must have increased the caller's credits by exactly the supplied amount.
        uint256 creditsIssued = afterImBal - beforeImBal;
        bool supplyLedgerOk = (creditsIssued == supplyAmount);

        // Try to redeem; this must not revert once the caller has credits.
        bool redeemReverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            redeemReverted = false;
            mAssetsActual = actual;
        } catch {
            redeemReverted = true;
        }

        // Credits remaining after the attempted redeem.
        uint256 finalImBal = c.imBalances(address(this));

        // Rule: if the requested amount is covered by the caller's credits, the redeem must succeed,
        // burn at most redeemAmount credits (from the caller), return a non-zero mAsset amount, and
        // leave the caller with a non-negative credit balance. If the requested amount exceeds the
        // caller's credits, the redeem must revert.
        bool covered = (redeemAmount <= afterImBal);
        assert(
            supplyLedgerOk &&
            (
                (!covered && redeemReverted) ||
                (covered && !redeemReverted && mAssetsActual > 0 && finalImBal <= afterImBal)
            )
        );
    }
}

