        require(to != address(0), "to zero");

        IERC20YieldToken mAsset = IERC20YieldToken(c.depositToken());
        uint256 contractBalBefore = mAsset.balanceOf(address(c));

        // approve the test contract to spend mAsset on behalf of from is not possible without a token mock;
        // instead we exercise supply only if the prior allowance/balance setup would allow it.
        // Precondition on params only, not on c's state.
